func (conf *Config) checkAndSetDefaults(ctx context.Context) error {
	if conf.Client == nil {
		client, err := utils.NewInstanceMetadataClient(ctx)
		if err != nil {
			return trace.Wrap(err)
		}
		conf.Client = client
	}
	if conf.Clock == nil {
