func TestIsEC2NodeID(t *testing.T) {
	// EC2 Node IDs are {AWS account ID}-{EC2 resource ID} eg:
	//   123456789012-i-1234567890abcdef0
	// AWS account ID is always a 12 digit number, see
	//   https://docs.aws.amazon.com/general/latest/gr/acct-identifiers.html
	// EC2 resource ID is i-{8 or 17 hex digits}, see
	//   https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/resource-ids.html
	testCases := []struct {
		name     string
		id       string
		expected bool
	}{
		{
			name:     "8 digit",
			id:       "123456789012-i-12345678",
			expected: true,
		},
		{
			name:     "17 digit",
			id:       "123456789012-i-1234567890abcdef0",
			expected: true,
		},
		{
			name:     "foo",
			id:       "foo",
			expected: false,
		},
		{
			name:     "uuid",
			id:       uuid.NewString(),
			expected: false,
		},
	}
	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			assert.Equal(t, IsEC2NodeID(tc.id), tc.expected)
		})
	}
}

func TestInstanceMetadataClientOptions(t *testing.T) {
	imdsClient := imds.New(imds.Options{})
	client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imdsClient))
	require.NoError(t, err)
	assert.Same(t, imdsClient, client.c)

	optionErr := errors.New("option failed")
	client, err = NewInstanceMetadataClient(context.Background(), func(*InstanceMetadataClient) error {
		return optionErr
	})
	assert.Nil(t, client)
	assert.ErrorIs(t, err, optionErr)

	client, err = NewInstanceMetadataClient(context.Background(), WithIMDSClient(nil))
	assert.Nil(t, client)
	assert.Error(t, err)
}

func TestInstanceMetadataClientIsAvailable(t *testing.T) {
	for _, tc := range []struct {
		name      string
		id        string
		available bool
	}{
		{name: "short ID", id: "i-1a2b3c4d", available: true},
		{name: "long ID", id: "i-1234567890abcdef0", available: true},
		{name: "HTML response", id: "<html>Login</html>"},
		{name: "extra characters", id: "i-12345678\n"},
		{name: "wrong length", id: "i-123456789"},
		{name: "uppercase", id: "i-ABCDEF12"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				switch {
				case r.Method == http.MethodPut && r.URL.Path == "/latest/api/token":
					_, _ = w.Write([]byte("token"))
				case r.Method == http.MethodGet && r.URL.Path == "/latest/meta-data/instance-id":
					_, _ = w.Write([]byte(tc.id))
				default:
					t.Errorf("unexpected metadata request: %s %s", r.Method, r.URL.Path)
					http.NotFound(w, r)
				}
			}))
			defer server.Close()

			client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{Endpoint: server.URL})))
			require.NoError(t, err)
			assert.Equal(t, tc.available, client.IsAvailable(context.Background()))
		})
	}
}

